-- GITADORA Skill Simulator GF/DM v17 migration
-- Source: GITADORA_GF_DM_曲難易度一覧.xls
-- 17494 charts / 1621 songs
-- Existing user scores, HOT flags, users and favorites are preserved.

begin;

-- GF + DM parts
alter table public.songs drop constraint if exists songs_part_check;
alter table public.songs add constraint songs_part_check check (part = any (array[
  'BSC-G','ADV-G','EXT-G','MAS-G','BSC-B','ADV-B','EXT-B','MAS-B',
  'BSC-D','ADV-D','EXT-D','MAS-D'
]::text[]));

alter table public.song_requests drop constraint if exists song_requests_part_allowed;
alter table public.song_requests drop constraint if exists song_requests_part_check;
alter table public.song_requests add constraint song_requests_part_allowed check (part = any (array[
  'BSC-G','ADV-G','EXT-G','MAS-G','BSC-B','ADV-B','EXT-B','MAS-B',
  'BSC-D','ADV-D','EXT-D','MAS-D'
]::text[]));

-- User-list / skill RPCs become GF/DM aware.
drop function if exists public.get_user_skill_targets(uuid);
drop function if exists public.get_user_skill_targets(uuid,text);
create function public.get_user_skill_targets(p_user_id uuid, p_instrument text default 'GF')
returns table(score_id uuid, song_id uuid, is_hot boolean, title text, part text, level numeric, achievement_rate numeric, skill numeric, fc text, play_option text)
language sql stable security definer set search_path to '' as $$
with scored as (
  select us.id score_id, us.song_id, s.is_hot, s.title, s.part, s.level,
         us.achievement_rate,
         trunc((s.level * 20 * us.achievement_rate / 100.0)::numeric,2) skill,
         us.fc, us.play_option, us.updated_at
  from public.user_scores us join public.songs s on s.id=us.song_id
  where us.user_id=p_user_id
    and s.title !~* '\(CLASSIC\)[[:space:]]*$'
    and ((upper(coalesce(p_instrument,'GF'))='DM' and s.part like '%-D')
      or (upper(coalesce(p_instrument,'GF'))<>'DM' and (s.part like '%-G' or s.part like '%-B')))
), ranked as (
  select *, row_number() over(partition by title order by skill desc,updated_at desc) title_rank from scored
)
select score_id,song_id,is_hot,title,part,level,achievement_rate,skill,fc,play_option
from ranked where title_rank=1 order by skill desc,title;
$$;
revoke execute on function public.get_user_skill_targets(uuid,text) from public, anon;
grant execute on function public.get_user_skill_targets(uuid,text) to authenticated;

drop function if exists public.list_user_summaries(text);
drop function if exists public.list_user_summaries(text,text);
create function public.list_user_summaries(p_search text default '', p_instrument text default 'GF')
returns table(user_id uuid, username text, total_skill numeric, last_recorded_at timestamptz, is_favorite boolean, is_self boolean)
language sql stable security definer set search_path to '' as $$
with scored as (
  select us.user_id,s.title,s.is_hot,
         trunc((s.level*20*us.achievement_rate/100.0)::numeric,2) skill,us.updated_at
  from public.user_scores us join public.songs s on s.id=us.song_id
  where s.title !~* '\(CLASSIC\)[[:space:]]*$'
    and ((upper(coalesce(p_instrument,'GF'))='DM' and s.part like '%-D')
      or (upper(coalesce(p_instrument,'GF'))<>'DM' and (s.part like '%-G' or s.part like '%-B')))
), best_part as (
  select *,row_number() over(partition by user_id,title order by skill desc,updated_at desc) title_rank from scored
), type_ranked as (
  select *,row_number() over(partition by user_id,is_hot order by skill desc,title) type_rank
  from best_part where title_rank=1
), totals as (
  select user_id,coalesce(sum(skill) filter(where type_rank<=25),0)::numeric total_skill
  from type_ranked group by user_id
), last_records as (
  select us.user_id,max(us.updated_at) last_recorded_at
  from public.user_scores us
  left join public.songs s on s.id=us.song_id
  left join public.song_requests sr on sr.id=us.song_request_id
  where ((upper(coalesce(p_instrument,'GF'))='DM' and coalesce(s.part,sr.part) like '%-D')
    or (upper(coalesce(p_instrument,'GF'))<>'DM' and (coalesce(s.part,sr.part) like '%-G' or coalesce(s.part,sr.part) like '%-B')))
  group by us.user_id
)
select p.id,p.username,coalesce(t.total_skill,0)::numeric,lr.last_recorded_at,
       exists(select 1 from public.user_favorites f where f.user_id=(select auth.uid()) and f.favorite_user_id=p.id),
       p.id=(select auth.uid())
from public.profiles p
left join totals t on t.user_id=p.id
left join last_records lr on lr.user_id=p.id
where p.username<>'admin' and (coalesce(p_search,'')='' or p.username like '%'||p_search||'%')
order by coalesce(t.total_skill,0) desc,p.username asc;
$$;
revoke execute on function public.list_user_summaries(text,text) from public, anon;
grant execute on function public.list_user_summaries(text,text) to authenticated;

