-- Existing rows keep IDs, so existing user_scores remain linked.
update public.songs s set level=st.level, updated_at=now()
from gitadora_master_stage st where s.title=st.title and s.part=st.part and s.level is distinct from st.level;

insert into public.songs(title,part,level,is_hot)
select st.title,st.part,st.level,coalesce(h.is_hot,false)
from gitadora_master_stage st
left join (select title,bool_or(is_hot) is_hot from public.songs group by title) h on h.title=st.title
left join public.songs s on s.title=st.title and s.part=st.part
where s.id is null;

-- Remove obsolete master rows only when no user score/request depends on them.
delete from public.songs s
where not exists(select 1 from gitadora_master_stage st where st.title=s.title and st.part=s.part)
  and not exists(select 1 from public.user_scores us where us.song_id=s.id)
  and not exists(select 1 from public.song_requests sr where sr.current_song_id=s.id);

commit;

-- Verification
select
  count(distinct title) as song_titles,
  count(*) filter(where part like '%-D') as dm_charts,
  count(*) filter(where part like '%-G' or part like '%-B') as gf_charts,
  count(*) as total_charts
from public.songs;
